  bitola: [
    { name: 'Şirok Sokak', desc: 'Bitola’nın “konsoloslar şehri” olarak anıldığı 19. yüzyılda pek çok Avrupa ülkesinin konsolosluğuna ev sahipliği yapan bu zarif yaya caddesi, neoklasik ve barok cepheli binalarıyla kentin en canlı damarıdır. Kafeleri ve tarihî mimarisiyle şehrin kozmopolit geçmişini yaşatır.' },
    { name: 'Heraklea Lynkestis', desc: 'MÖ 4. yüzyılda Makedonya Kralı II. Filip tarafından kurulan bu antik kent, Roma ve erken Bizans dönemlerinde önemli bir merkez olmuştur. Olağanüstü korunmuş renkli taban mozaikleri, antik tiyatrosu ve bazilikalarıyla bölgenin en değerli arkeolojik alanlarından biridir.' },
    { name: 'Saat Kulesi & Eski Çarşı', desc: '16. yüzyıla uzanan köklü Osmanlı çarşısı ve şehrin simgesi 30 metrelik Saat Kulesi, Bitola’nın yüzyıllar boyu bir ticaret merkezi olduğunu gösterir. Bezisten (kapalı çarşı) ve çevresindeki dükkânlar hâlâ geleneksel el sanatlarını ve pazar kültürünü sürdürür.' },
    { name: 'Pelister Milli Parkı', desc: 'Kuzey Makedonya’nın en eski milli parkı olan Pelister, buzul çağından kalma “Dağ Gözleri” adlı berrak göller ve endemik Molika çamı ormanlarıyla ünlüdür. Bitola’ya yakınlığıyla yürüyüş ve doğa tutkunları için eşsiz bir kaçış noktasıdır.' },
  ],
  trebinje: [
    { name: 'Arslanagić (Perović) Köprüsü', desc: 'İki kemerli tarihî Osmanlı köprüsü.' },
    { name: 'Eski Şehir (Kastel)', desc: 'Surlar içinde çınarlı meydan ve cami.' },
    { name: 'Hercegovačka Gračanica', desc: 'Tepeden kente hâkim manastır ve manzara.' },
    { name: 'Şarap Mahzenleri', desc: 'Çevre bağlarda yerel şarap tadımı.' },
  ],
  ston: [
    { name: 'Ston Surları', desc: '14. yüzyılda Dubrovnik Cumhuriyeti’nin değerli tuzlalarını korumak için inşa edilen bu 5 kilometrelik savunma hattı, “Avrupa’nın Çin Seddi” olarak anılır. Tepeler boyunca yürünebilen surlar, çevresindeki tuz tarlaları ve körfez manzarasıyla eşsiz bir tarih yürüyüşü sunar.' },
    { name: 'Tuzlalar', desc: 'Ston’un varlığının kaynağı olan bu tuzlalar, güneş ve rüzgârla çalışan geleneksel yöntemlerle Avrupa’nın en eski faal tuz üretim tesisleri arasındadır. “Beyaz altın” denen bu tuz, bir zamanlar Dubrovnik Cumhuriyeti’ne büyük zenginlik kazandırmıştır.' },
    { name: 'Mali Ston & İstiridye', desc: 'Ston’un kardeş kasabası Mali Ston’un körfezi, Romalılar döneminden beri övülen dünyaca ünlü istiridyeleriyle tanınır. Tatlı ve tuzlu suyun buluştuğu bu berrak sularda taze toplanan istiridye ve midyeler, bölgeyi bir gastronomi durağına dönüştürür.' },
    { name: 'Pelješac Bağ Yolu', desc: 'Ston’dan uzanan Pelješac Yarımadası, güçlü Dingač ve Postup kırmızı şaraplarına kaynaklık eden dik ve güneşli bağlarıyla Hırvatistan’ın en ünlü şarap bölgelerinden biridir. Bağlar arasından geçen yol, tadım duraklarıyla Adriyatik manzarasını birleştirir.' },
  ],

